import PhotoSwipeLightbox from './vendor/photoswipe/photoswipe-lightbox.esm.js';
const photos = [["photo-42.jpg", 1200, 900, "Piscinas compartilhadas do condomínio"], ["estadia-09.webp", 960, 1280, "Quarto de casal com ar-condicionado"], ["estadia-02.webp", 960, 1280, "Sala de estar com acesso à varanda"], ["estadia-14.webp", 960, 1280, "Cozinha equipada do apartamento"], ["estadia-25.webp", 960, 1280, "Mesa de jantar junto à cozinha"], ["estadia-07.webp", 960, 1280, "Varanda com mesa e cadeiras"], ["estadia-00.webp", 960, 1280, "Segundo quarto de casal"], ["estadia-12.webp", 960, 1280, "Banheiro do apartamento"], ["photo-49.jpg", 1200, 879, "Praia de Guaibim"], ["photo-40.jpg", 1200, 800, "Área externa do condomínio"], ["photo-44.jpg", 1200, 726, "Vista das piscinas"], ["photo-45.jpg", 1200, 1600, "Área de lazer compartilhada"], ["estadia-10.webp", 960, 1280, "Quarto com cama de casal e armário"], ["photo-52.jpg", 1200, 861, "Fim de tarde em Guaibim"], ["photo-56.jpg", 1200, 2151, "Coqueiros na orla de Guaibim"], ["photo-63.jpg", 1200, 862, "A praia ao entardecer"], ["estadia-15.webp", 960, 1280, "Bancada e fogão na cozinha"], ["estadia-17.webp", 960, 1280, "Micro-ondas e forno elétrico"], ["estadia-20.webp", 960, 1280, "Cafeteira e utensílios à disposição"], ["estadia-27.webp", 960, 1280, "Lavanderia com máquina de lavar"], ["estadia-28.webp", 960, 1280, "Área de serviço"], ["estadia-30.webp", 960, 1280, "Panelas e recipientes da cozinha"], ["estadia-33.webp", 960, 1280, "Copos, pratos e utensílios"], ["estadia-06.webp", 960, 1280, "Armário de um dos quartos"]].map(([file,width,height,alt])=>({src:`assets/${file}`,width,height,alt}));
const lightbox=new PhotoSwipeLightbox({dataSource:photos,pswpModule:()=>import('./vendor/photoswipe/photoswipe.esm.js'),bgOpacity:.97,showHideAnimationType:'fade',closeTitle:'Fechar galeria',zoomTitle:'Ampliar foto',arrowPrevTitle:'Foto anterior',arrowNextTitle:'Próxima foto',errorMsg:'Não foi possível carregar esta foto.'});
lightbox.on('uiRegister',()=>{lightbox.pswp.ui.registerElement({name:'custom-caption',order:9,isButton:false,appendTo:'root',onInit:(element,pswp)=>{pswp.on('change',()=>{element.textContent=photos[pswp.currIndex].alt;});}});});
lightbox.init();
document.querySelectorAll('[data-gallery-index]').forEach(trigger=>trigger.addEventListener('click',event=>{event.preventDefault();lightbox.loadAndOpen(Number(trigger.dataset.galleryIndex));}));
const rooms=document.getElementById('rooms-track');
const previous=document.getElementById('rooms-prev');
const next=document.getElementById('rooms-next');
const updateArrows=()=>{previous.disabled=rooms.scrollLeft<5;next.disabled=rooms.scrollLeft+rooms.clientWidth>=rooms.scrollWidth-5;};
const moveRooms=direction=>{const step=rooms.querySelector('article').getBoundingClientRect().width+parseFloat(getComputedStyle(rooms).gap);rooms.scrollBy({left:step*direction,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};
previous.addEventListener('click',()=>moveRooms(-1));next.addEventListener('click',()=>moveRooms(1));rooms.addEventListener('scroll',updateArrows,{passive:true});new ResizeObserver(updateArrows).observe(rooms);updateArrows();
const arrival=document.getElementById('arrival');const departure=document.getElementById('departure');
const localDate=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const nextDay=value=>{const date=new Date(`${value}T12:00:00`);date.setDate(date.getDate()+1);return localDate(date);};
arrival.min=localDate(new Date());departure.min=nextDay(arrival.min);
arrival.addEventListener('change',()=>{if(!arrival.value)return;departure.min=nextDay(arrival.value);if(departure.value&&departure.value<=arrival.value)departure.value='';departure.setCustomValidity('');});
departure.addEventListener('change',()=>departure.setCustomValidity(''));
document.getElementById('booking-form').addEventListener('submit',event=>{event.preventDefault();if(departure.value<=arrival.value){departure.setCustomValidity('A saída deve ser depois da chegada.');departure.reportValidity();return;}const format=value=>value.split('-').reverse().join('/');const guests=document.getElementById('guests').value;const message=`Olá, Luciana! Gostaria de consultar a disponibilidade do Refúgio Cachoeira Guaibim.\nChegada: ${format(arrival.value)}\nSaída: ${format(departure.value)}\nHóspedes: ${guests}\nPode me informar os valores e as condições de reserva?`;window.open(`https://wa.me/553492528131?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');});
document.getElementById('year').textContent=new Date().getFullYear();
